import inspect
import pandas as pd

def task_func(f_list, file_path):
    if not isinstance(f_list, list):
        raise ValueError("The 'f_list' must be a list of functions.")

    if not f_list:
        raise ValueError("The 'f_list' cannot be empty.")

    if not isinstance(file_path, str):
        raise ValueError("The 'file_path' must be a valid string.")

    try:
        data = []
        for func in f_list:
            if not inspect.isfunction(func):
                raise ValueError("Each element in 'f_list' must be a function.")

            func_signature = inspect.signature(func)
            func_name = func.__name__
            num_args = len(func_signature.parameters)
            defaults = {k: v.default for k, v in func_signature.parameters.items() if v.default is not inspect.Parameter.empty}
            annotations = {k: v.annotation for k, v in func_signature.parameters.items() if v.annotation is not inspect.Parameter.empty}
            is_lambda = func.__name__ == "<lambda>"

            data.append({
                'Function Name': func_name,
                'Number of Arguments': num_args,
                'Defaults': defaults,
                'Annotations': annotations,
                'Is Lambda': is_lambda
            })

        df = pd.DataFrame(data)
        df.to_csv(file_path, index=False)
        print(f"Specs exported to {file_path}")
    except IOError as e:
        print(f"Error writing to file: {e}")

import json
from glob import glob

def task_func(directory, string):
    # Find all JSON files in the directory and its subdirectories
    json_files = glob(f"{directory}/**/*.json", recursive=True)

    # Initialize a list to store the paths of files containing the string
    result = []

    # Iterate over each JSON file
    for json_file in json_files:
        try:
            # Open the JSON file and load its content
            with open(json_file, 'r') as file:
                data = json.load(file)

                # Recursively search for the string within the JSON data structure
                if search_string(data, string):
                    result.append(json_file)
        except json.JSONDecodeError:
            # Skip files that are not valid JSON
            continue

    return result

def search_string(data, target):
    # Base case: if the data is a string, check if it contains the target
    if isinstance(data, str) and target in data:
        return True

    # If the data is a list or dictionary, recursively search each element
    if isinstance(data, (list, dict)):
        for item in data:
            if search_string(item, target):
                return True

    return False

