import pandas as pd

def task_func(json_str):
    # Parse the JSON string into a dictionary
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()  # Return an empty DataFrame if JSON parsing fails

    # Normalize the data by doubling numerical values
    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, (int, float)):
            normalized_data[key] = value * 2
        elif isinstance(value, list):
            normalized_data[key] = [x * 2 if isinstance(x, (int, float)) else x for x in value]
        elif isinstance(value, str) and re.match(r'^-?\d+(\.\d+)?$', value):
            normalized_data[key] = float(value) * 2
        else:
            normalized_data[key] = value

    # Create a DataFrame from the normalized data
    df = pd.DataFrame(normalized_data)

    return df

