import itertools

def task_func(data_list, file_name):
    if not data_list:
        return []

    # Extract numeric values and their positions
    positions = {}
    for row in data_list:
        for i in range(1, len(row)):
            if isinstance(row[i], (int, float)):
                if i not in positions:
                    positions[i] = []
                positions[i].append(row[i])

    # Calculate mean for each position
    means = {}
    for pos, values in positions.items():
        means[pos] = np.mean(values)

    # Write the results to a text file
    with open(file_name, 'w') as file:
        for pos, mean in means.items():
            file.write(f"Position {pos}: {mean}\n")

    # Return the list of calculated mean values
    return list(means.values())
